create.example:
const { Vector3 } = kcds.math;

const walls = kcds.characters.PatrolRoute.create({
  name: 'walls',
  points: [new Vector3(1650, 2150, 37), new Vector3(1680, 2150, 37), new Vector3(1680, 2180, 37)],
  mode: 'pingPong',
  speed: 'walk',
  waitSeconds: 5,
});
guard.patrol(walls);

getById.exampleCs:
var route = PatrolRoute.GetById("walls-north");
if (route != null)
{
    guard.Patrol(route);
}

getByName.exampleCs:
var route = PatrolRoute.GetByName("walls");
if (route != null)
{
    guard.Patrol(route);
}

